function earliestWindow(slotsA: number[][], slotsB: number[][], duration: number): number[] {
  let best = Infinity;
  for (const [a1, b1] of slotsA)
    for (const [a2, b2] of slotsB) {
      const lo = Math.max(a1, a2), hi = Math.min(b1, b2);
      if (hi - lo >= duration) best = Math.min(best, lo);
    }
  return best === Infinity ? [] : [best, best + duration];
}

