class Solution:
    def earliestWindow(self, slotsA: List[List[int]], slotsB: List[List[int]], duration: int) -> List[int]:
        best = None
        for a1, b1 in slotsA:
            for a2, b2 in slotsB:
                lo, hi = max(a1, a2), min(b1, b2)
                if hi - lo >= duration and (best is None or lo < best):
                    best = lo
        return [] if best is None else [best, best + duration]

