function earliestWindow(slotsA: number[][], slotsB: number[][], duration: number): number[] {
  const A = [...slotsA].sort((x, y) => x[0] - y[0]);
  const B = [...slotsB].sort((x, y) => x[0] - y[0]);
  let i = 0, j = 0;
  while (i < A.length && j < B.length) {
    const lo = Math.max(A[i][0], B[j][0]);
    const hi = Math.min(A[i][1], B[j][1]);
    if (hi - lo >= duration) return [lo, lo + duration];
    if (A[i][1] < B[j][1]) i++;
    else j++;
  }
  return [];
}

